// 接口响应解密。
// 请求固定携带 Token: "0" 与 Tokenparam: "0,2.1.11"（服务器不校验其新鲜度），
// 服务器用 Tokenparam 里的时间戳派生密钥：md5(ts + '185Hcomic3PAPP7R') 的
// 32 字符 hex 文本按 UTF-8 取 32 字节，AES-256-ECB 加密响应 data 字段。
// 时间戳固定为 "0"，密钥即常量，一次解密即可，无需尝试多个候选。
fn dec(b64) {
  let key = bytes(md5('0' + '185Hcomic3PAPP7R'))
  return json(trim(fromBytes(decrypt('AES/ECB/PKCS5Padding', base64Bytes(b64), key, ''))))
}

// 排序变量映射为接口排序码（App 真实码：''=最新, tf=爱心, mv=总榜, mv_m=月榜, mv_w=周榜）。
// 「最新发布」用 mr：在 categories/filter 上与空值等效，在 search 上必须非空。
fn sc(name) {
  return lookup({'最新发布': 'mr', '最多爱心': 'tf', '总排行': 'mv', '月排行': 'mv_m', '周排行': 'mv_w'}, name, 'mr')
}

// 正文图片域名替换为用户选定线路：接口下发的图片域名是轮询的（非按网络优化），
// 且各图片 CDN 域名均可访问同一路径，故统一替换到 vars.imgHost，
// 某条线路不通/慢时在书源设置切换即可（实测全部可用，见使用说明）。
fn imgLine(u, host) {
  let i = indexOf(u, '://')
  if (i < 0) { return u }
  let rest = substring(u, i + 3, len(u))
  let j = indexOf(rest, '/')
  if (j < 0) { return u }
  return host + substring(rest, j, len(rest))
}

// 线路选项显示「线路N 地址」→ 取地址部分；纯地址原样返回
fn lineHost(s) {
  let a = split(s, ' ')
  return default(a[1], s)
}

