function jmJparse(t, what) {
  try { return JSON.parse(t); }
  catch (e) { throw new Error(what + " JSON解析失败，输入前60字符: " + String(t).slice(0, 60)); }
}

function jmUtf8(s) {
  var out = [];
  for (var i = 0; i < s.length; i++) {
    var c = s.charCodeAt(i);
    if (c < 0x80) out.push(c);
    else if (c < 0x800) { out.push(0xC0 | (c >> 6), 0x80 | (c & 63)); }
    else { out.push(0xE0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63)); }
  }
  return new Uint8Array(out);
}
function jmImageDecode(bytes, ctx) {
  var m = String(ctx.url || '').match(/\/media\/photos\/(\d+)\/([^\/?]+)/);
  if (!m) return bytes;
  var name = m[2];
  try { name = decodeURIComponent(name); } catch (e) { }
  if (/\.gif$/i.test(name)) return bytes;
  var aid = m[1], path5 = name.substring(0, 5), num = 1;
  var a = parseInt(aid, 10);
  if (a >= 220980) {
    if (a < 268850) num = 10;
    else {
      var d = image.hash('MD5', jmUtf8(aid + path5));
      var nib = d[d.length - 1] & 15;
      var k = nib < 10 ? 48 + nib : 87 + nib;
      k = (a <= 421925) ? k % 10 : k % 8;
      num = (k >= 0 && k <= 9) ? k * 2 + 2 : 10;
    }
  }
  if (num <= 1) return bytes;
  return image.reorderStrips(bytes, { count: num, remainder: 'last', format: 'image/webp', quality: 90 });
}

function content(ctx) {
  try {
    var __r = (function (ctx) {
      var curl = String((ctx.chapter && ctx.chapter.url) || ctx.url || '');
      var m = /id=(\d+)/.exec(curl);
      if (!m) throw new Error('章节地址缺少 id：' + curl);
      var id = m[1];
      var sm = /^https?:\/\/[^\/]+/.exec(curl);
      var server = sm ? sm[0] : __hostOf(ctx.vars && ctx.vars.server, 'https://www.cdnutc.cc');
      var imgHost = __hostOf(ctx.vars && ctx.vars.imgHost, 'https://cdn-msp.jmapiproxy1.cc');
      var tryServers = [server].concat(SM_SERVERS)
        .filter(function (v, i, a) { return v && a.indexOf(v) === i; }).slice(0, 3);
      var d = null, usedServer = null, lastErr = null;
      for (var round = 0; round < 2 && !d; round++) {
        if (round > 0) sleep(600);
        for (var si = 0; si < tryServers.length && !d; si++) {
          var sv = tryServers[si];
          var rr = http.get(sv + '/comic_read?id=' + id, { headers: { 'Token': '0', 'Tokenparam': '0,2.1.11' } });
          if (!rr || (!rr.ok && !rr.body)) { lastErr = 'HTTP ' + (rr ? rr.status : 0); continue; }
          var tt = String(rr.body || '').replace(/^\uFEFF/, '').trim();
          var ee = null;
          try { ee = jmJparse(tt, '接口响应'); } catch (e2) { lastErr = e2.message; continue; }
          if (ee.code !== 200) { lastErr = 'code=' + ee.code + ' ' + (ee.errorMsg || ''); continue; }
          try {
            var pp = native.decrypt('AES/ECB/PKCS5Padding', native.base64Bytes(ee.data), native.md5('0' + '185Hcomic3PAPP7R'), '');
            var dd = JSON.parse(native.fromBytes(pp));
            if (dd.images && dd.images.length) { d = dd; usedServer = sv; }
            else lastErr = 'images 空';
          } catch (e4) { lastErr = '解密失败: ' + e4.message; }
        }
      }
      if (!d) throw new Error('所有线路均失败（' + lastErr + '）');
      var paths = (d.images || []).map(function (x) { return typeof x === 'string' ? x : (x && x.image); }).filter(Boolean);
      if (!paths.length) throw new Error('章节没有图片');
      var urls = paths.map(function (u) { return imgHost + String(u).replace(/^https?:?(?::\/\/|\/\/)[^\/]+/, ''); });
      return { images: urls };
    })(ctx);
    if (!__r || !__r.images || !__r.images.length) {
      throw new Error("正文脚本未返回图片列表");
    }
    return { images: __r.images.map(String) };
  } catch (e) {
    var msg = "content 脚本失败: " + ((e && e.message) || e);
    throw new Error(msg);
  }
}

// 「线路N 地址」→ 地址；纯地址/空原样回退
function __hostOf(s, fb) {
  s = String(s || '');
  if (/^自动/.test(s)) return fb;
  var i = s.indexOf(' ');
  return (i > 0 ? s.substring(i + 1).trim() : s) || fb;
}

// ===== 设置区操作按钮（懒人有声同款） =====
var SM_SERVERS = ['https://www.cdnhjk.net', 'https://www.cdnutc.cc', 'https://www.cdngwc.net', 'https://www.cdngwc.club', 'https://www.cdnutc.me', 'https://www.cdngwc.cc'];
var SM_IMGS = ['https://cdn-msp.jmapiproxy1.cc', 'https://cdn-msp.jmapiproxy2.cc', 'https://cdn-msp2.jmapiproxy2.cc', 'https://cdn-msp3.jmapiproxy2.cc', 'https://cdn-msp.jmapinodeudzn.net', 'https://cdn-msp3.jmapinodeudzn.net'];
var SM_HD = { 'User-Agent': 'okhttp/4.9.1', 'Token': '0', 'Tokenparam': '0,2.1.11' };
var SM_NUMS = ['①', '②', '③', '④', '⑤', '⑥'];
function smName(host, list) { var i = list.indexOf(host); return i >= 0 ? ('线路' + SM_NUMS[i] + ' ' + host) : host; }
function smProbe(url) {
  var t0 = Date.now();
  try {
    var r = http.get(url, { headers: SM_HD, timeout: 8000 });
    var st = (r && r.status) || 0;
    return { ok: st === 200, st: st, ms: Date.now() - t0 };
  } catch (e) { return { ok: false, st: 0, ms: Date.now() - t0, err: (e && e.message) || String(e) }; }
}
function smProbeList(list, path) {
  var out = [];
  for (var i = 0; i < list.length; i++) {
    var r = smProbe(list[i] + path);
    out.push({ n: smName(list[i], list), u: list[i], ok: r.ok, st: r.st, ms: r.ms, err: r.err || '' });
  }
  return out;
}
function optServerList() {
  var items = smProbeList(SM_SERVERS, '/categories/filter?page=1&o=mr');
  items.sort(function(a, b) { return (a.ok ? a.ms : 999999) - (b.ok ? b.ms : 999999); });
  return items.map(function(x) { return x.n; });
}
function optImgList() {
  var items = smProbeList(SM_IMGS, '/media/albums/100001_3x4.jpg');
  items.sort(function(a, b) { return (a.ok ? a.ms : 999999) - (b.ok ? b.ms : 999999); });
  return items.map(function(x) { return x.n; });
}
// ===== 三按钮：诊断 / 重测速并应用 / 恢复默认 =====
function actDiagnose() {
  var sv = smProbeList(SM_SERVERS, '/categories/filter?page=1&o=mr');
  var im = smProbeList(SM_IMGS, '/media/albums/100001_3x4.jpg');
  var i, j, fails = 0, fixed = [], bestS = null, bestI = null, lines = [], imgs = [];
  for (i = 0; i < sv.length; i++) {
    if (!sv[i].ok) fails++;
    if (sv[i].ok && (!bestS || sv[i].ms < bestS.ms)) bestS = sv[i];
    lines.push('  ' + (sv[i].ok ? '✅' : '❌') + ' ' + sv[i].n.replace('https://', '') + '  ' + sv[i].ms + 'ms HTTP ' + sv[i].st + (sv[i].ok ? '' : '  ' + (sv[i].err || '')));
  }
  for (i = 0; i < im.length; i++) {
    if (!im[i].ok) fails++;
    if (im[i].ok && (!bestI || im[i].ms < bestI.ms)) bestI = im[i];
    imgs.push('  ' + (im[i].ok ? '✅' : '❌') + ' ' + im[i].n.replace('https://', '') + '  ' + im[i].ms + 'ms HTTP ' + im[i].st + (im[i].ok ? '' : '  ' + (im[i].err || '')));
  }
  var curS = String(vars.get('server') || ''), curI = String(vars.get('imgHost') || ''), sOk = true, iOk = true;
  if (curS) { sOk = false; for (j = 0; j < sv.length; j++) if (sv[j].n === curS) sOk = sv[j].ok; }
  if (curI) { iOk = false; for (j = 0; j < im.length; j++) if (im[j].n === curI) iOk = im[j].ok; }
  if (!sOk && bestS) { vars.set('server', bestS.n); fixed.push('浏览线路 ' + curS + ' 不通 → 已切到 ' + bestS.n); }
  if (!iOk && bestI) { vars.set('imgHost', bestI.n); fixed.push('图片线路 ' + curI + ' 不通 → 已切到 ' + bestI.n); }
  if (fixed.length) { try { ui.refreshExplore(); } catch (e) {} }
  var head;
  if (!fails && !fixed.length) head = '🩺 诊断结果：✅ 浏览线路与图片线路全部可用';
  else if (fixed.length) head = '🩺 诊断结果：⚠️ ' + fails + ' 处异常，已自动修复 ' + fixed.length + ' 处，现在可以正常使用';
  else head = '🩺 诊断结果：❌ ' + fails + ' 处异常，且无可替代线路';
  var out = [head, '  当前 浏览 ' + (sOk ? curS || '默认' : bestS ? bestS.n : '无可用') + ' · 图片 ' + (iOk ? curI || '默认' : bestI ? bestI.n : '无可用')];
  for (i = 0; i < fixed.length; i++) out.push('  🔧 ' + fixed[i]);
  out.push('', '浏览线路（分类/搜索接口）');
  out = out.concat(lines);
  out.push('', '图片线路（正文图+封面）');
  out = out.concat(imgs);
  return out.join('\n');
}
function actRetest() {
  var sv = smProbeList(SM_SERVERS, '/categories/filter?page=1&o=mr');
  var best = null;
  for (var i = 0; i < sv.length; i++) if (sv[i].ok && (!best || sv[i].ms < best.ms)) best = sv[i];
  if (!best) return '❌ 全部浏览线路不可用，请稍后重试';
  vars.set('server', best.n);
  var im = smProbeList(SM_IMGS, '/media/albums/100001_3x4.jpg');
  var bestImg = null;
  for (var k = 0; k < im.length; k++) if (im[k].ok && (!bestImg || im[k].ms < bestImg.ms)) bestImg = im[k];
  var msg = '⚡ 重测速完成，已应用最快线路\n✅ 浏览线路已切换: ' + best.n + ' (' + best.ms + 'ms)';
  if (bestImg) { vars.set('imgHost', bestImg.n); msg += '\n✅ 图片线路已切换: ' + bestImg.n + ' (' + bestImg.ms + 'ms)'; }
  try { ui.refreshExplore(); } catch (e2) {}
  return msg;
}

function actReset() {
  vars.set('server', '线路⑤ https://www.cdnutc.me');
  vars.set('imgHost', '线路⑤ https://cdn-msp.jmapinodeudzn.net');
  try { ui.refreshExplore(); } catch (e2) {}
  return '♻️ 已复位默认线路（浏览⑤ / 图片⑤）';
}
